action.command:
cat > /tmp/scan2.mjs <<'EOF'
import fs from "fs";
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
// context around key lines
function ctx(n, before=4, after=8){
  console.log("---- around line", n, "----");
  for(let i=Math.max(0,n-before); i<Math.min(lines.length, n+after); i++){
    console.log(i, lines[i].trim().slice(0,150));
  }
}
ctx(145455);
ctx(193624, 6, 6);
// search for numeric defaults like 1440, 2880, 720 near 'age' or 'Age'
for (let n=0;n<lines.length;n++){
  const m = lines[n];
  if (/(1440|2880|4320|720)\b/.test(m) && /age|Age|release|Release/.test(m)) console.log("NUM:", n, m.trim().slice(0,140));
}
EOF
node /tmp/scan2.mjs 2>&1 | head -60

